// The text to show people for a value, or NULL for a value without one.
static inline const char *connectorx_fatal_error_type_label(connectorx_fatal_error_type_t value) {
  switch (value) {
    case CONNECTORX_FATAL_ERROR_TYPE_INIT_ERROR: return "Initialization Error";
    case CONNECTORX_FATAL_ERROR_TYPE_BAD_CONFIG: return "Bad Configuration";
    case CONNECTORX_FATAL_ERROR_TYPE_START_TASK: return "Start Task Error";
    case CONNECTORX_FATAL_ERROR_TYPE_CREATE_QUEUE: return "Create Queue Error";
    default: return NULL;
  }
}

